using System.Net;
using System.Text.Json;
using Htt.Host.Api;
using Htt.Host.Api.MasterData;
using Htt.Infrastructure.Documents;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class CrmAttachmentTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);private static Guid Id(JsonElement e)=>e.GetProperty("id").GetGuid();
 private async Task<(Guid Customer,Guid Branch)> Branch(HttpClient c){var cust=await Create(c,"/customers",new CustomerDraft(Code(),"Attachment customer",null));return(cust,await Create(c,$"/customers/{cust}/branches",new BranchMaintenance(Code(),"Store","10 Test Street","Sydney","NSW","2000")));}
 private static JsonElement E(object o)=>JsonSerializer.SerializeToElement(o,ApiJson.Options);
 private static readonly byte[] Png=[137,80,78,71,13,10,26,10,0];
 private async Task<HttpResponseMessage> Upload(HttpClient c,Guid parent,string? key=null,long version=1)
 {using var r=new HttpRequestMessage(HttpMethod.Post,$"/api/v1/documents/{parent}/attachments?fileName=site.png");r.Headers.Add("Idempotency-Key",key??Code());r.Headers.TryAddWithoutValidation("If-Match",$"\"{version}\"");r.Content=new ByteArrayContent(Png);r.Content.Headers.ContentType=new("image/png");return await c.SendAsync(r);}
 private sealed class Scanner(bool clean=true,Func<Task>? callback=null,bool fail=false):IFileScanner{public int Calls;public async Task<bool> IsCleanAsync(byte[] x,CancellationToken ct){Calls++;if(callback is not null)await callback();if(fail)throw new DocumentWorkException("temporary_scanner",WorkFailure.Retry);return clean;}}
 private sealed class Pdf:IPdfRenderer{public Task<byte[]> RenderAsync(JsonElement x,CancellationToken ct)=>throw new InvalidOperationException("Unexpected PDF work");}private sealed class Mail:IDocumentMailer{public Task<string> SendAsync(Guid id,JsonElement x,CancellationToken ct)=>throw new InvalidOperationException("Unexpected mail");}
 private async Task Run(Scanner scanner){await S("DELETE FROM platform.document_job_attempts WHERE company_id<>@c;DELETE FROM platform.document_jobs WHERE company_id<>@c",("c",db.Company));await using var source=NpgsqlDataSource.Create(db.Worker);Assert.True(await new DocumentWorker(source,new Pdf(),scanner,new Mail()).ProcessOneAsync());}
 [Theory][InlineData("NOTE")][InlineData("BOARD")][InlineData("VISIT")][InlineData("DRAFT")][InlineData("CUSTOMER_DRAFT")]
 public async Task CRM_entities_reuse_scan_and_authorized_private_download(string kind)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);Guid parent;if(kind is"DRAFT"or"CUSTOMER_DRAFT")parent=await Create(c,"/crm/drafts",new CrmDraftInput(Guid.NewGuid(),kind=="DRAFT"?"CONTACT":"CUSTOMER",kind=="DRAFT"?b.Customer:null,new("Attachment draft",kind=="CUSTOMER_DRAFT"?Code():null)));else{object data=kind switch{"NOTE"=>new CustomerNote("Site note"),"BOARD"=>new DisplayBoard("Oak",DateTimeOffset.UtcNow.AddDays(-1)),_=>new VisitCheckIn(new(-33.86m,151.21m,10,DateTimeOffset.UtcNow))};parent=await Create(c,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),kind,b.Customer,b.Branch,E(data)));}var upload=await Expect(await Upload(c,parent),HttpStatusCode.Accepted);var file=Id(upload);await Expect(await Send(c,HttpMethod.Get,$"/files/{file}/content"),HttpStatusCode.Conflict);await Run(new());var response=await Send(c,HttpMethod.Get,$"/files/{file}/content");Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Equal(Png,await response.Content.ReadAsByteArrayAsync());Assert.NotEmpty((await Get(c,$"/documents/{parent}/files")).GetProperty("items").EnumerateArray());await Expect(await Send(c,HttpMethod.Post,$"/documents/{parent}/pdf",version:1),HttpStatusCode.UnprocessableEntity);}
 [Fact]public async Task Sharing_scope_protects_attachment_metadata_download_and_cached_upload()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var staff=await Staff(db,"SALES");await S("INSERT INTO identity.customer_assignments(company_id,membership_id,customer_id)VALUES(@c,@m,@cust)",("c",db.Company),("m",staff.Membership),("cust",b.Customer));using var sales=api.Authenticated(staff.Subject);var note=await Create(c,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",b.Customer,b.Branch,E(new CustomerNote("Private","PRIVATE"))));var key=Code();var file=Id(await Expect(await Upload(c,note,key),HttpStatusCode.Accepted));await Run(new());await Expect(await Send(sales,HttpMethod.Get,$"/documents/{note}/files"),HttpStatusCode.Forbidden);await Expect(await Send(sales,HttpMethod.Get,$"/files/{file}/content"),HttpStatusCode.Forbidden);await Expect(await Upload(sales,note,key),HttpStatusCode.Forbidden);}
 [Fact]public async Task Malware_scan_rejection_never_exposes_bytes()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var note=await Create(c,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",b.Customer,b.Branch,E(new CustomerNote("Photos"))));var file=Id(await Expect(await Upload(c,note),HttpStatusCode.Accepted));await Run(new(false));Assert.Equal("REJECTED",await S("SELECT state FROM platform.files WHERE company_id=@c AND id=@id",("c",db.Company),("id",file)));await Expect(await Send(c,HttpMethod.Get,$"/files/{file}/content"),HttpStatusCode.Conflict);}
 [Theory][InlineData(false)][InlineData(true)]public async Task Scope_revoked_during_scan_prevents_verification(bool during)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var staff=await Staff(db,"SALES");await S("INSERT INTO identity.customer_assignments(company_id,membership_id,customer_id)VALUES(@c,@m,@cust)",("c",db.Company),("m",staff.Membership),("cust",b.Customer));using var sales=api.Authenticated(staff.Subject);var note=await Create(sales,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",b.Customer,b.Branch,E(new CustomerNote("Photos"))));var u=await Expect(await Upload(sales,note),HttpStatusCode.Accepted);async Task Revoke(){await S("DELETE FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m",("c",db.Company),("m",staff.Membership));}if(!during)await Revoke();var scanner=new Scanner(callback:during?Revoke:null);await Run(scanner);Assert.Equal(during?1:0,scanner.Calls);Assert.Equal("PENDING",await S("SELECT state FROM platform.files WHERE company_id=@c AND id=@id",("c",db.Company),("id",Id(u))));Assert.Equal("FAILED",await S("SELECT state FROM platform.document_jobs WHERE id=@id",("id",u.GetProperty("jobId").GetGuid())));await Expect(await Send(sales,HttpMethod.Get,$"/files/{Id(u)}/content"),HttpStatusCode.Forbidden);}
 [Fact]public async Task Revoked_attachment_cannot_be_downloaded_and_emits_sync_tombstone()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var note=await Create(c,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",b.Customer,b.Branch,E(new CustomerNote("Photos"))));var file=Id(await Expect(await Upload(c,note),HttpStatusCode.Accepted));await Run(new());var key=Code();await Expect(await Send(c,HttpMethod.Post,$"/files/{file}/revoke",version:2,key:key),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Post,$"/files/{file}/revoke",version:2,key:key),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Get,$"/files/{file}/content"),HttpStatusCode.NotFound);Assert.True((long)(await S("SELECT count(*)FROM crm.collaboration_changes WHERE company_id=@c AND entity_type='ATTACHMENT'AND tombstone",("c",db.Company)))!>=1);}
 [Fact]public async Task Concurrent_same_key_upload_creates_one_file_and_scan_job()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var note=await Create(c,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",b.Customer,b.Branch,E(new CustomerNote("Photos"))));var key=Code();var results=await Task.WhenAll(Upload(c,note,key),Upload(c,note,key));Assert.Equal(Id(await Expect(results[0],HttpStatusCode.Accepted)),Id(await Expect(results[1],HttpStatusCode.Accepted)));Assert.Equal(1L,await S("SELECT count(*)FROM platform.file_assets WHERE company_id=@c",("c",db.Company)));Assert.Equal(1L,await S("SELECT count(*)FROM platform.document_jobs WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Late_upload_audit_failure_rolls_back_private_bytes_job_and_sync_event_then_key_retries()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var note=await Create(c,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",b.Customer,b.Branch,E(new CustomerNote("Photos"))));var key=Code();await S($"CREATE FUNCTION crm.test_c05_uploadfail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='documents.attachment_uploaded'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c05_uploadfail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION crm.test_c05_uploadfail()");try{await Expect(await Upload(c,note,key),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM platform.files WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM platform.document_jobs WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.collaboration_changes WHERE company_id=@c AND entity_type='ATTACHMENT'",("c",db.Company)));}finally{await S("DROP TRIGGER test_c05_uploadfail ON platform.audit_events;DROP FUNCTION crm.test_c05_uploadfail()");}await Expect(await Upload(c,note,key),HttpStatusCode.Accepted);}
 [Fact]public async Task Retryable_scan_can_recover_without_duplicate_attachment()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var note=await Create(c,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",b.Customer,b.Branch,E(new CustomerNote("Photos"))));var u=await Expect(await Upload(c,note),HttpStatusCode.Accepted);await Run(new(fail:true));await S("UPDATE platform.document_jobs SET available_at=now()WHERE id=@id",("id",u.GetProperty("jobId").GetGuid()));await Run(new());Assert.Equal("VERIFIED",await S("SELECT state FROM platform.files WHERE id=@id",("id",Id(u))));Assert.Equal(1L,await S("SELECT count(*)FROM platform.file_assets WHERE company_id=@c",("c",db.Company)));}
 [Theory][InlineData("collaboration_history")][InlineData("collaboration_changes")][InlineData("branch_geocodes")][InlineData("geocode_jobs")][InlineData("collaboration_objects")]public async Task App_cannot_mutate_CRM_history_changes_or_geocode_cache(string table)
 {await using var session=await db.SessionAsync();await using var cmd=new NpgsqlCommand("DELETE FROM crm."+table,session.Connection,session.Transaction);Assert.Equal("42501",(await Assert.ThrowsAsync<PostgresException>(()=>cmd.ExecuteNonQueryAsync())).SqlState);}
}
